"""Static HTML assembly only; reads small metadata, does not process images."""
import json,html
from pathlib import Path
root=Path(__file__).resolve().parents[3]
out=root/'runs/hemp-sam3-grid-search-v1';out.mkdir(parents=True,exist_ok=True)
data={}
for folder in ['grid-search','resolution-low','resolution-native']:
 p=out/'results'/folder
 if (p/'report.json').exists():data[folder]={'report':json.loads((p/'report.json').read_text()),'organs':json.loads((p/'semantic-audit.json').read_text()) if (p/'semantic-audit.json').exists() else {}}
# Retain original semantic audit while adding the separately recorded refinement.
refine=out/'results/grid-refinement/report.json'
if refine.exists() and 'grid-search' in data:
    for row in data['grid-search']['report']['results']: row['asset_folder']='grid-search'
    extra=json.loads(refine.read_text())['results']
    for row in extra: row['asset_folder']='grid-refinement'
    data['grid-search']['report']['results']+= [r for r in extra if r['prompt']=='leaf']
    data['grid-search']['report']['results'].sort(key=lambda r:r['grid'])
sources=json.loads((out/'results/source-probe/sources.json').read_text()) if (out/'results/source-probe/sources.json').exists() else {}
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SAM3 — grid scale and organ audit</title><style>
:root{color-scheme:light}body{margin:0;background:#eff1e8;color:#1e382f;font:17px/1.5 system-ui}main{max-width:1450px;margin:auto;padding:36px}h1{font-size:42px;line-height:1.1}h2{margin-top:42px}p{max-width:1050px}.muted{color:#53695d}.card{padding:24px;background:#fffdf5;border:1px solid #b7c6b8;border-radius:18px;margin:20px 0}select,button{font:inherit;padding:9px 14px;background:white;border:1px solid #839c8d;border-radius:8px;color:inherit}label{margin-right:22px}.images{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.images img{width:100%;height:560px;object-fit:contain;background:#11170f;border-radius:9px;image-rendering:auto}.images figure{margin:0}figcaption{font-size:15px;margin-top:8px}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}td,th{text-align:left;padding:9px;border-bottom:1px solid #d4ddce}tr.best{background:#dcead9}a{color:#1a6556}.legend{display:flex;gap:20px;flex-wrap:wrap}.swatch{display:inline-block;width:13px;height:13px;margin-right:5px}.note{border-left:4px solid #c28b33;padding-left:15px}summary{cursor:pointer}code{font-size:14px}#status{font-size:22px;font-weight:600}.scroll{overflow-x:auto}@media(max-width:800px){main{padding:18px}.images{grid-template-columns:1fr}.images img{height:440px}h1{font-size:32px}}
</style><main><p class="muted">ASTRAFACTORY · REMOTE PERCEPTION EXPERIMENT</p><h1>How much plant did we actually segment?</h1><p id="status"></p><p class="note"><strong>Target reference requirement:</strong> living plants rooted in their pots, upright in the intended indoor or greenhouse setting, with natural leaf posture and visible attachment structure. Detached-shoot images below are archived diagnostics, not target anatomy references.</p><p>Compare the same pixels across crop sizes. Green shows covered plant, red shows missed plant and blue shows definite-background leakage. The foreground estimate is a fixed color-based proxy, not hand-labeled ground truth.</p>
<div class="card"><label>Image <select id="dataset"><option value="grid-search">Original reference · 381×444</option><option value="resolution-low">Archived excised shoot · downsized</option><option value="resolution-native">Archived excised shoot · native</option></select></label><label>Confidence <select id="threshold"><option value="0.5">0.50 — primary</option><option value="0.25">0.25 — diagnostic</option><option value="0.1">0.10 — diagnostic</option></select></label><label>Grid <select id="grid"></select></label><div class="images" style="margin-top:24px"><figure><img id="input"><figcaption>Reference. Open image for native-resolution inspection.</figcaption></figure><figure><img id="proxy"><figcaption>Bright green: conservative core. Dark green: foreground estimate. Olive: uncertain edge band. Gray: excluded frame/support.</figcaption></figure><figure><img id="coverage"><figcaption id="caption"></figcaption></figure></div><div class="legend"><span><i class="swatch" style="background:#3ccd8c"></i>Covered plant</span><span><i class="swatch" style="background:#f04155"></i>Missed plant</span><span><i class="swatch" style="background:#4691ff"></i>Background leakage</span></div></div>
<h2>Measured grid comparison</h2><p>Grid n×n means n² overlapping crops. Empty-background crops are skipped using the same fixed foreground estimate; their false positives are not tested. Coverage includes crop-edge fragments. The highlighted row has the highest foreground-proxy IoU among the completed grids at the selected threshold.</p><div class="card scroll"><table><thead><tr><th>Grid</th><th>Crop pixels</th><th>Processed / total</th><th>Plant coverage</th><th>Core coverage</th><th>Proxy IoU</th><th>Background / prediction</th><th>Seconds</th></tr></thead><tbody id="rows"></tbody></table></div><p class="note">These percentages measure area, not how many leaves were correctly identified. A large merged mask can score high coverage. Disconnected fragments can cover tissue without establishing an organ boundary or identity.</p>
<h2>Which organs does it propose?</h2><p>Text prompts propose leaf/leaflet, stem and flower regions at two crop scales selected from the initial sweep (before the refinement). Conflicting labels stay purple; unclassified plant stays yellow. These are unverified semantic proposals. No unknown region is silently assigned to a leaf.</p><div class="card"><div class="images"><figure><img id="organInput"><figcaption>Reference</figcaption></figure><figure><img id="organs"><figcaption>Proposed organ labels, clipped to the foreground estimate for display only. Raw coverage metrics above are not clipped.</figcaption></figure><div><div class="legend"><span><i class="swatch" style="background:#42bf7a"></i>Leaf tissue</span><span><i class="swatch" style="background:#36ace9"></i>Stem</span><span><i class="swatch" style="background:#e662aa"></i>Flower</span><span><i class="swatch" style="background:#a464e7"></i>Conflicting</span><span><i class="swatch" style="background:#f7be35"></i>Unclassified</span></div><div id="organStats"></div><p id="downloads"></p></div></div></div>
<details class="card"><summary>Archived source mismatch — detached shoots, rejected for living-plant fitting</summary><h2>Segmentation diagnostics only</h2><p>Morales, Griffiths and Topp: <a href="https://zenodo.org/records/17783092">Hemp root and shoot diversity image dataset</a>, CC BY 4.0. Six inspected samples are 4000×6000 pixels. These show excised shoots on cloth. The user rejected them as references for the intended living, upright, potted plant. Retained only to document the completed resolution experiment; do not fit target plant posture, branching angles, occlusion or mechanics from them. The native-versus-downsized experiment uses the exact same fixed crop.</p><a href="results/source-probe/contact-sheet.png"><img src="results/source-probe/contact-sheet.png" style="max-width:100%;width:1000px"></a><p>The original reference is from <a href="https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0252985">Anderson et al., PLOS ONE (2021)</a>. Its Fig. 1 caption describes plants one week before harvest, but the current crop does not show the pot and is not a verified match to the intended task stage. High-resolution and original-reference results are separate specimens and must not be treated as a controlled comparison with each other.</p></details>
<details class="card"><summary>Evidence, limitations and reproduction</summary><p>All model inference and image processing ran on RunPod. The Mac transported artifacts and assembled this static review. No plant geometry, robot policy, cultivation schedule or pruning plan was changed.</p><ul><li>Primary threshold was fixed before the sweep; lower thresholds are diagnostic.</li><li>Grid quality is non-monotonic. This is an empirical sweep, not binary search or proof of a universal optimum.</li><li>Foreground thresholds miss some dark or non-green tissue. White holder and image border are excluded.</li><li>Overlapping leaf and leaflet detections are not added into a biological leaf count.</li><li>Organ masks need boundary-level review and labeled evaluation before being used as anatomy ground truth.</li></ul><p><a href="results/grid-search/report.json">Original report</a> · <a href="results/grid-search/semantic-audit.json">Semantic audit</a> · <a href="results/resolution-native/report.json">Native-resolution report</a> · <a href="results/source-probe/sources.json">Source metadata</a> · <a href="results/execution.json">GPU shutdown receipt</a></p></details></main><script>
const data=DATA;const ds=document.querySelector('#dataset'),th=document.querySelector('#threshold'),grid=document.querySelector('#grid');const pct=x=>(100*x).toFixed(1)+'%';
function img(id,path){const el=document.getElementById(id);el.src=path;el.onclick=()=>window.open(path,'_blank');el.style.cursor='zoom-in'}
function render(reset=false){const key=ds.value,d=data[key];if(!d)return;const t=+th.value,rs=d.report.results.filter(q=>q.prompt==='leaf');if(reset){grid.innerHTML=rs.map(q=>`<option value="${q.grid}">${q.grid}×${q.grid}</option>`).join('');grid.value=rs.some(q=>q.grid===10)?'10':String(rs[0].grid)}let best=-1,bi=-1;rs.forEach((q,i)=>{let m=q.all_mask_metrics.find(m=>m.threshold===t);if(q.complete_run&&m.proxy_iou>best){best=m.proxy_iou;bi=i}});document.querySelector('#rows').innerHTML=rs.map((q,i)=>{let m=q.all_mask_metrics.find(m=>m.threshold===t);return `<tr class="${i===bi?'best':''}"><td>${q.grid}×${q.grid}${q.complete_run?'':' (partial)'}</td><td>${q.crop_size.join('×')}</td><td>${q.processed} / ${q.total_tiles}</td><td>${pct(m.foreground_coverage)}</td><td>${pct(m.core_coverage)}</td><td>${pct(m.proxy_iou)}</td><td>${pct(m.background_fraction_of_prediction)}</td><td>${q.seconds.toFixed(1)}</td></tr>`}).join('');if(reset&&bi>=0)grid.value=String(rs[bi].grid);let q=rs.find(q=>q.grid===+grid.value)||rs[0],m=q.all_mask_metrics.find(m=>m.threshold===t),base='results/'+key+'/';img('input',base+'input.png');img('proxy',base+'foreground-proxy.png');img('coverage','results/'+(q.asset_folder||key)+'/leaf-'+q.grid+'/coverage-'+t+'.png');img('organInput',base+'input.png');img('organs',base+'organs-'+t+'.png');document.querySelector('#caption').textContent=`${q.grid}×${q.grid} · ${pct(m.foreground_coverage)} estimated plant coverage · confidence ≥${t}.`;document.querySelector('#status').textContent=bi<0?'Experiment incomplete':`Best tested grid by area IoU at confidence ${t}: ${rs[bi].grid}×${rs[bi].grid}.`;document.querySelector('#downloads').innerHTML=`<a href="${base}foreground-mask.png">Foreground mask</a> · <a href="${base}plant-cutout.png">Transparent cutout</a> · <a href="${base}proposed-organ-labels-${t}.png">Organ label IDs (PNG)</a>`;const s=d.organs.results?.find(x=>x.threshold===t);document.querySelector('#organStats').innerHTML=s?'<p>Share of estimated plant area:</p>'+['leaf_only','stem_only','flower_only','conflicting_labels','unclassified'].map(k=>`<p>${k.replaceAll('_',' ')}: <b>${pct(s[k]/s.foreground)}</b></p>`).join(''):'Semantic audit pending';}
ds.onchange=()=>render(true);th.onchange=()=>render();grid.onchange=()=>render();render(true);
</script></html>'''
(out/'index.html').write_text(page.replace('DATA',json.dumps(data)))
print(out/'index.html')
